/**
 * NodeLink contract tests on AlgoKit LocalNet (requires Docker + `algokit localnet start`).
 * Exercises the real Groth16 verifier on-chain with proofs generated by snarkjs.
 *
 *   NODELINK_NETWORK=localnet npx tsx --test tests/localnet.test.ts
 */
import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { microAlgo } from "@algorandfoundation/algokit-utils";
import algosdk from "algosdk";
import {
  BN254_SCALAR_FIELD,
  PUBLIC_PROFILE_BOX_MBR,
  PoseidonMerkleTree,
  bigIntToBytes,
  boxName,
  bytesToBigInt,
  computeNullifierHash,
  decodeHotStatus,
  decodeLeafDepositedLog,
  generateCommitment,
  readBox,
  type CommitmentSecrets,
} from "@nodelink/shared";
import type { NodeLinkProtocolClient } from "@nodelink/shared/generated";
import { makeAlgorand } from "../lib/env";
import { proveMembership, terminateSnarkjsWorkers } from "../lib/prover";
import { claimStatus, deployProtocol, depositCommitment, type Signer } from "../lib/protocol";
import type { AlgorandClient } from "@algorandfoundation/algokit-utils";

const TTL = 1_000n;

async function expectFailure(p: Promise<unknown>, pattern: RegExp, label: string): Promise<void> {
  try {
    await p;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    assert.match(msg, pattern, `${label}: unexpected error ${msg.slice(0, 400)}`);
    return;
  }
  assert.fail(`${label}: expected failure`);
}

describe("NodeLinkProtocol on LocalNet", { timeout: 600_000 }, () => {
  let algorand: AlgorandClient;
  let admin: Signer;
  let onlineCold: Signer;
  let app: NodeLinkProtocolClient; // real online check (no bypass)
  let appBypass: NodeLinkProtocolClient; // testnet-style bypass flag
  let hot: Signer;
  let attacker: Signer;
  const tierOneLeaves: bigint[] = [];
  let mine: CommitmentSecrets;
  let proof: { proof: Uint8Array; publicInputs: Uint8Array; publicSignals: string[] };

  const fund = async (amountAlgo: number): Promise<Signer> => {
    const acct = algorand.account.random();
    await algorand.account.ensureFundedFromEnvironment(acct.addr, microAlgo(amountAlgo * 1_000_000));
    return acct;
  };

  before(async () => {
    algorand = await makeAlgorand("localnet");
    admin = await fund(20);
    // LocalNet genesis (KMD) accounts are online consensus participants.
    onlineCold = await algorand.account.localNetDispenser();
    hot = await fund(2);
    attacker = await fund(2);
    app = await deployProtocol(algorand, admin, { statusTtlRounds: TTL, testnetSkipOnlineCheck: false });
    appBypass = await deployProtocol(algorand, admin, { statusTtlRounds: TTL, testnetSkipOnlineCheck: true });
  });

  after(async () => {
    await terminateSnarkjsWorkers();
  });

  it("rejects deposits from accounts that are not online participants", async () => {
    const offline = await fund(10);
    await expectFailure(depositCommitment(algorand, app, offline, generateCommitment(1).leaf, 1), /not an online consensus participant/, "offline");
  });

  it("accepts a deposit from an online participant and emits LeafDeposited", async () => {
    for (let i = 0; i < 3; i++) {
      const c = generateCommitment(1);
      await depositCommitment(algorand, app, onlineCold, c.leaf, 1);
      tierOneLeaves.push(c.leaf);
    }
    mine = generateCommitment(1);
    const res = await app.send.depositCommitment({
      sender: onlineCold.addr,
      args: {
        commitment: bigIntToBytes(mine.leaf, 32),
        declaredTier: 1n,
        mbrPayment: algorand.createTransaction.payment({ sender: onlineCold.addr, receiver: app.appAddress, amount: microAlgo(23_700) }),
      },
    });
    assert.equal(res.return, 3n);
    tierOneLeaves.push(mine.leaf);
    const logs = res.confirmations.at(-1)?.logs ?? [];
    const ev = logs.map((l) => decodeLeafDepositedLog(l)).find((e) => e !== null);
    assert.ok(ev, "LeafDeposited event present");
    assert.equal(ev.commitment, mine.leaf);
    assert.equal(ev.tier, 1);
    assert.equal(ev.leafIndex, 3);
  });

  it("rejects duplicate commitments, non-canonical commitments and under-funded tiers", async () => {
    await expectFailure(depositCommitment(algorand, app, onlineCold, mine.leaf, 1), /already deposited/, "dup");
    await expectFailure(depositCommitment(algorand, app, onlineCold, mine.leaf + BN254_SCALAR_FIELD, 1), /non-canonical/, "canonical");
    const small = await fund(5);
    await expectFailure(depositCommitment(algorand, appBypass, small, generateCommitment(2).leaf, 2), /below declared tier/, "tier threshold");
    // bypass app: Scout deposit from a non-online account succeeds (testnet-only flag)
    const r = await depositCommitment(algorand, appBypass, small, generateCommitment(1).leaf, 1);
    assert.equal(r.leafIndex, 0n);
  });

  it("only the root updater can post roots; admin can rotate the role", async () => {
    const tree = new PoseidonMerkleTree(tierOneLeaves);
    await expectFailure(
      app.send.postRoot({ sender: attacker.addr, args: { root: bigIntToBytes(tree.root, 32), tier: 1n, leafCount: 4n } }),
      /root updater only/,
      "unauthorised post",
    );
    await expectFailure(
      app.send.postRoot({ sender: admin.addr, args: { root: bigIntToBytes(tree.root, 32), tier: 1n, leafCount: 5n } }),
      /exceeds deposits/,
      "leaf count",
    );
    await expectFailure(app.send.setRootUpdater({ sender: attacker.addr, args: { newRootUpdater: attacker.addr.toString() } }), /admin only/, "rotate");
    const r = await app.send.postRoot({ sender: admin.addr, args: { root: bigIntToBytes(tree.root, 32), tier: 1n, leafCount: 4n } });
    assert.equal(r.return, 0n);
    const known = await app.send.isKnownRoot({ args: { root: bigIntToBytes(tree.root, 32), tier: 1n } });
    assert.equal(known.return, true);
    const wrongTier = await app.send.isKnownRoot({ args: { root: bigIntToBytes(tree.root, 32), tier: 2n } });
    assert.equal(wrongTier.return, false);
  });

  it("verifies a real Groth16 proof on-chain and records the hot status", async () => {
    const tree = new PoseidonMerkleTree(tierOneLeaves);
    proof = await proveMembership({ secret: mine.secret, nullifier: mine.nullifier, tier: 1, path: tree.path(3), hotWalletAddress: hot.addr.toString() });
    const res = await claimStatus(algorand, app, hot, proof.proof, proof.publicInputs);
    assert.equal(res.tier, 1);
    console.log(`    claim_status fee paid: ${res.fee} microAlgos`);
    const raw = await readBox(algorand.client.algod, app.appId, boxName.hotStatus(hot.addr.toString()));
    assert.ok(raw);
    const status = decodeHotStatus(raw);
    assert.equal(status?.tier, 1);
    assert.equal(status?.expiryRound, res.expiryRound);
    const nul = await readBox(algorand.client.algod, app.appId, boxName.nullifier(computeNullifierHash(mine.nullifier)));
    assert.ok(nul, "nullifier box created");
    const view = await app.send.getStatus({ args: { hot: hot.addr.toString() } });
    assert.equal(view.return?.active, true);
  });

  it("rejects replays (nullifier already used)", async () => {
    await expectFailure(claimStatus(algorand, app, hot, proof.proof, proof.publicInputs, true), /nullifier already used/, "replay");
  });

  it("rejects a stolen proof submitted by a third-party address (front-running)", async () => {
    await expectFailure(claimStatus(algorand, app, attacker, proof.proof, proof.publicInputs), /different hot wallet/, "front-run");
  });

  it("rejects tampered public inputs", async () => {
    const tampered = (idx: number, value: bigint): Uint8Array => {
      const copy = proof.publicInputs.slice();
      copy.set(bigIntToBytes(value, 32), idx * 32);
      return copy;
    };
    const signal = (i: number): bigint => bytesToBigInt(proof.publicInputs.slice(i * 32, i * 32 + 32));
    // nullifierHash + r: same scalar for the pairing, different box key -> must be rejected
    await expectFailure(claimStatus(algorand, app, hot, proof.proof, tampered(0, signal(0) + BN254_SCALAR_FIELD), true), /non-canonical/, "non-canonical");
    // fresh nullifier hash -> passes replay check but the pairing fails
    await expectFailure(claimStatus(algorand, app, hot, proof.proof, tampered(0, signal(0) + 1n), true), /invalid proof/, "forged nullifier");
    // tier mismatch with the root's tier tree
    await expectFailure(claimStatus(algorand, app, hot, proof.proof, tampered(1, 2n), true), /unknown root for this tier/, "tier");
    // unknown root
    await expectFailure(claimStatus(algorand, app, hot, proof.proof, tampered(2, 12345n), true), /unknown root/, "root");
  });

  it("rejects any attempt to rekey through the protocol", async () => {
    await expectFailure(
      app.send.depositCommitment({
        sender: onlineCold.addr,
        rekeyTo: attacker.addr,
        args: {
          commitment: bigIntToBytes(generateCommitment(1).leaf, 32),
          declaredTier: 1n,
          mbrPayment: algorand.createTransaction.payment({ sender: onlineCold.addr, receiver: app.appAddress, amount: microAlgo(23_700) }),
        },
      }),
      /rekey not allowed/,
      "rekey",
    );
  });

  it("public profile reveal requires the cold wallet's co-signature and can be hidden", async () => {
    const cold = onlineCold;
    // MBR paid by the hot wallet instead of the cold wallet -> rejected
    await expectFailure(
      app.send.revealPublicProfile({
        sender: hot.addr,
        args: {
          coldAddress: cold.addr.toString(),
          mbrPayment: algorand.createTransaction.payment({ sender: hot.addr, receiver: app.appAddress, amount: microAlgo(PUBLIC_PROFILE_BOX_MBR) }),
        },
      }),
      /cold wallet must co-sign/,
      "co-sign",
    );
    await app.send.revealPublicProfile({
      sender: hot.addr,
      args: {
        coldAddress: cold.addr.toString(),
        mbrPayment: algorand.createTransaction.payment({ sender: cold.addr, receiver: app.appAddress, amount: microAlgo(PUBLIC_PROFILE_BOX_MBR) }),
      },
    });
    const raw = await readBox(algorand.client.algod, app.appId, boxName.publicProfile(hot.addr.toString()));
    assert.ok(raw);
    assert.equal(algosdk.encodeAddress(raw), cold.addr.toString());
    await app.send.hidePublicProfile({ sender: hot.addr, args: [], coverAppCallInnerTransactionFees: true, maxFee: microAlgo(5_000) });
    assert.equal(await readBox(algorand.client.algod, app.appId, boxName.publicProfile(hot.addr.toString())), null);
  });

  it("is immutable (update/delete rejected)", async () => {
    await expectFailure(algorand.send.appDelete({ sender: admin.addr, appId: app.appId }), /./, "delete");
  });
});
